function frame(t){
  const dt=Math.min(.05,Math.max(0,(t-lastTime)/1000));lastTime=t;
  if(running()){const before=new Map(game.state.objects.map(o=>[o.id,{...o}]));handle(game.update(dt),before);sync();saveClock+=dt;if(saveClock>=2){saveClock=0;save()}
    const s=game.state,token=`${s.startedAt}:${s.stageIndex}`;if(s.context==='sleep'&&s.levelIndex===2&&s.stopAvailable&&sleepOfferToken!==token){sleepOfferToken=token;sleepChoice()}
  }
  sync();
  renderer.render({...game.state,backgrounds:['home','landing','onboarding'].includes(ui)?game.profile.selectedBackgrounds:game.state.backgrounds,skin:['home','landing','onboarding'].includes(ui)?game.profile.selectedSkin:game.state.skin,skinData:skinList().find(s=>s.id===(['home','landing','onboarding'].includes(ui)?game.profile.selectedSkin:game.state.skin)),scene:['home','landing','onboarding'].includes(ui)?'home':game.state.scene,paused:ui!=='playing'||game.state.paused,training:game.state.isTutorial},t/1000);audio.update({...game.state,paused:ui!=='playing'||game.state.paused},dt);
  hudClock+=dt;if(hudClock>.1){hudClock=0;renderHUD()}requestAnimationFrame(frame)
}
